import {replacePageMarkup} from './stable-surface.js';
import {surfaceTheme} from './styles/theme.js';
import {defaultScheduleTracking} from '../shared/settings/model.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);

// A settings child surface. Draft inputs stay mounted during edits and saves.
export function mountScheduleSettingsView(container,{settings,controls,onBack=()=>{},onClose=()=>{},onSchedule=()=>{}}={}){
 const lifetime=new AbortController();let snapshot=null,draft=defaultScheduleTracking(),disposed=false,saving=false,failed=false,pending=null,recoveringControls=false,controlFailure='';
 const button=(label,action,tone='tertiary')=>`<button type="button" class="ui-button ui-button--${tone}" data-schedule-action="${action}">${label}</button>`;
 const icon=(label,action,name)=>`<button type="button" class="ui-icon-button ui-button--tertiary" aria-label="${label}" data-schedule-action="${action}"><img class="lt-icon" src="${new URL(`./icons/${name}.svg`,import.meta.url)}" alt=""></button>`;
 try{snapshot=settings.captureScheduleTracking();draft=structuredClone(snapshot.config);}catch{failed=true;}
 function error(text=''){const node=container.querySelector('[data-schedule-error]');if(node){node.textContent=text;node.hidden=!text;}const retry=container.querySelector('[data-schedule-action="reload"]');if(retry)retry.hidden=!text;}
 function patch(){if(disposed)return;const status=controls?.inspect?.(),enabled=status?.controls?.features?.schedule===true;
  const toggle=container.querySelector('[data-schedule-action="enabled"]');if(toggle){toggle.setAttribute('aria-checked',String(enabled));toggle.disabled=saving||recoveringControls||status?.status!=='ready';}
  const controlError=controlFailure||status?.error||(status?.status==='unconfirmed'?'功能开关保存尚未确认，请重新读取开关。':'');
  const controlMessage=container.querySelector('[data-schedule-control-error]');if(controlMessage){controlMessage.textContent=controlError;controlMessage.hidden=!controlError;}
  const controlRetry=container.querySelector('[data-schedule-action="reload-controls"]');if(controlRetry){controlRetry.hidden=!controlError;controlRetry.disabled=saving||recoveringControls||status?.status==='loading';}
  for(const node of container.querySelectorAll('[data-schedule-field]'))node.disabled=saving;
  for(const action of ['save','reset','reload']){const node=container.querySelector(`[data-schedule-action="${action}"]`);if(node)node.disabled=saving||(action==='save'&&failed);}
  const save=container.querySelector('[data-schedule-action="save"]');if(save)save.textContent=saving?'保存中…':'保存';
 }
 function read(){const node=container.querySelector('[data-schedule-field="instructions"]');if(node)draft.instructions=node.value;}
 function dirty(){read();return snapshot&&!equal(draft,snapshot.config);}
 function leave(action){if(saving)return;if(!dirty()){action();return;}pending=action;const dialog=container.querySelector('[data-schedule-dialog]');if(dialog)dialog.hidden=false;for(const node of container.querySelectorAll('.lt-header,.lt-main,.lt-footer'))node.inert=true;container.querySelector('[data-schedule-action="continue"]')?.focus?.({preventScroll:true});}
 function dismiss(){pending=null;const dialog=container.querySelector('[data-schedule-dialog]');if(dialog)dialog.hidden=true;for(const node of container.querySelectorAll('.lt-header,.lt-main,.lt-footer'))node.inert=false;}
 function render(){replacePageMarkup(container,`<section class="lantai lt-settings ui-workspace ui-graphic-controls" data-ui-theme="${surfaceTheme(container)}"><header class="lt-header ui-header ui-header--centered">${icon('返回功能管理','back','back')}<h1 class="ui-page-title">日程追踪</h1>${icon('关闭兰台','close','close')}</header><main class="lt-main ui-main lt-settings-main" tabindex="-1"><section class="lt-settings-group"><div class="lt-settings-row"><span>日程追踪</span><button type="button" class="ui-switch" role="switch" aria-label="日程追踪" data-schedule-action="enabled" aria-checked="false"><span class="ui-switch__track"><span class="ui-switch__knob"></span></span></button></div><p class="lt-meta">开启后从每轮正文提取安排；时间管理关闭时暂停提取与提醒。</p><p class="lt-error" role="alert" data-schedule-control-error hidden></p>${button('重新读取开关','reload-controls')}</section><section class="lt-settings-group"><h2>提取分类</h2>${[['schedule','日常安排'],['anniversary','纪念日候选']].map(([kind,label])=>`<label class="time-check"><input type="checkbox" data-schedule-field="category" value="${kind}" ${draft.categories.includes(kind)?'checked':''}>${label}</label>`).join('')}<p class="lt-meta">明确日期与安排自动加入日历。纪念日和待补全的安排先成为候选，启用后才会提醒。</p></section><section class="lt-settings-group"><label class="ui-field"><span class="ui-field__label">提取要求</span><textarea class="ui-input time-textarea lt-prompt-editor" rows="10" data-schedule-field="instructions">${esc(draft.instructions)}</textarea></label>${button('恢复默认','reset')}</section>${button('查看已有候选','candidates','secondary')}<p class="lt-status" role="status" data-schedule-status hidden></p><p class="lt-error" role="alert" data-schedule-error hidden></p>${button('重新读取','reload')}</main><footer class="lt-footer ui-action-footer">${button('保存','save','primary')}</footer><div class="time-confirm" role="dialog" aria-modal="true" aria-label="放弃修改" data-schedule-dialog hidden><p>放弃未保存的修改？</p><div>${button('继续编辑','continue')}${button('放弃修改','discard','primary')}</div></div></section>`);error(failed?'设置未能读取，请重新读取。':'');patch();}
 async function save(){if(saving||failed)return;read();if(typeof draft.instructions!=='string'||!draft.instructions.trim()||draft.instructions.length>20000){error('请填写提取要求（最多 20000 字）。');return;}const submitted=structuredClone(draft);saving=true;patch();error();try{if(!settings.matchesScheduleTracking(snapshot))throw new Error('日程追踪设置已变化，请重新读取后保存。');const receipt=await settings.saveScheduleTracking(submitted,{expectedEpoch:snapshot.epoch,isCurrent:()=>!disposed});if(disposed)return;if(receipt.status!=='committed')throw new Error('保存尚未确认，请重新读取。');snapshot=settings.captureScheduleTracking();draft=structuredClone(snapshot.config);error();const status=container.querySelector('[data-schedule-status]');if(status){status.hidden=false;status.textContent='已保存';}const retry=container.querySelector('[data-schedule-action="reload"]');if(retry)retry.hidden=true;}catch(failure){if(!disposed){failed=failure.code!=='INVALID_SETTINGS';error(failure.message);}}finally{saving=false;patch();}}
 container.addEventListener('input',event=>{if(event.target.dataset?.scheduleField==='instructions')draft.instructions=event.target.value;},{signal:lifetime.signal});
 container.addEventListener('change',event=>{const node=event.target;if(node.dataset?.scheduleField==='category'){draft.categories=['schedule','anniversary'].filter(kind=>kind===node.value?node.checked:draft.categories.includes(kind));}},{signal:lifetime.signal});
 container.addEventListener('click',event=>{const node=event.target.closest('[data-schedule-action]');if(!node||node.disabled||disposed)return;const action=node.dataset.scheduleAction;if(pending&&!['continue','discard'].includes(action))return;
  if(action==='back')leave(onBack);else if(action==='close')leave(onClose);else if(action==='candidates')leave(onSchedule);else if(action==='continue')dismiss();else if(action==='discard'){const next=pending;dismiss();next?.();}
  else if(action==='enabled')void Promise.resolve().then(()=>{controlFailure='';return controls.toggle('schedule');}).catch(failure=>{controlFailure=failure.message;patch();});
  else if(action==='reload-controls')void (async()=>{recoveringControls=true;controlFailure='';patch();try{await controls.refresh();}catch(failure){controlFailure=failure.message;}finally{recoveringControls=false;patch();}})();else if(action==='save')void save();else if(action==='reset'){draft.instructions=defaultScheduleTracking().instructions;const input=container.querySelector('[data-schedule-field="instructions"]');if(input)input.value=draft.instructions;}
  else if(action==='reload')void (async()=>{
   read();const before=snapshot?.config??defaultScheduleTracking(),edits=Object.fromEntries(Object.entries(draft).filter(([key,value])=>!equal(value,before[key])).map(([key,value])=>[key,structuredClone(value)]));saving=true;patch();
   try{await settings.read();if(disposed)return;snapshot=settings.captureScheduleTracking();draft={...structuredClone(snapshot.config),...edits};failed=false;
    const input=container.querySelector('[data-schedule-field="instructions"]');if(input)input.value=draft.instructions;
    for(const field of container.querySelectorAll('[data-schedule-field="category"]'))field.checked=draft.categories.includes(field.value);
    error();const status=container.querySelector('[data-schedule-status]');if(status){status.hidden=false;status.textContent=Object.keys(edits).length?'已重新读取；未保存的编辑已保留':'已重新读取';}
   }catch(failure){error(failure.message);}finally{saving=false;patch();}
  })();
 },{signal:lifetime.signal});
 container.addEventListener('keydown',event=>{if(!pending)return;if(event.key==='Escape'){event.preventDefault();dismiss();}else if(event.key==='Tab'){const nodes=[...container.querySelectorAll('[data-schedule-dialog] button')];if(!nodes.length)return;event.preventDefault();const index=nodes.indexOf(container.getRootNode().activeElement);nodes[(index+(event.shiftKey?-1:1)+nodes.length)%nodes.length]?.focus();}},{signal:lifetime.signal});
 const off=controls?.subscribe?.(patch);render();return {back(){leave(onBack);return true;},dispose(){disposed=true;lifetime.abort();off?.();}};
}
